export function isOpenOn(branch, isoDate) {
  return !branch.closedWeekdays.includes(weekdayOf(isoDate)) && !branch.holidays.includes(isoDate);
}""","""/**
 * Tells whether a branch is open on a calendar date: not on a closed weekday, nor on a holiday,
 * nor within a closure (a run of days, both ends included; a branch without closures has no field).
 */
export function isOpenOn(branch, isoDate) {
  return (
    !branch.closedWeekdays.includes(weekdayOf(isoDate)) &&
    !branch.holidays.includes(isoDate) &&
    !(branch.closures ?? []).some(({ from, to }) => from <= isoDate && isoDate <= to)
  );
}""")
open(p,'w').write(s)
